def minPathSumGrid(grid):
    n = len(grid[0])
    best = [0] * n
    for r, row in enumerate(grid):
        for c in range(n):
            if r == 0 and c == 0:
                best[c] = row[c]
            elif r == 0:
                best[c] = best[c - 1] + row[c]
            elif c == 0:
                best[c] += row[c]
            else:
                best[c] = row[c] + min(best[c], best[c - 1])
    return best[-1]
